import{_ as t,c as a,o as r,ag as o}from"./chunks/framework.DZ_cNctr.js";const p=JSON.parse(`{"title":"Does It Matter Where Your Data Lives? Local vs. Remote OME-ZARR","description":"Opening the same large microscopy dataset from local disk vs. a remote server reveals a lot about your storage setup. Here's what you need to know before choosing how to serve OME-ZARR files.","frontmatter":{"title":"Does It Matter Where Your Data Lives? Local vs. Remote OME-ZARR","description":"Opening the same large microscopy dataset from local disk vs. a remote server reveals a lot about your storage setup. Here's what you need to know before choosing how to serve OME-ZARR files.","date":"2026-03-08T00:00:00.000Z","author":"Find Nuclei"},"headers":[],"relativePath":"blog/local-vs-remote-ome-zarr.md","filePath":"blog/local-vs-remote-ome-zarr.md"}`),s={name:"blog/local-vs-remote-ome-zarr.md"};function n(i,e,l,c,d,h){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="does-it-matter-where-your-data-lives-local-vs-remote-ome-zarr" tabindex="-1">Does It Matter Where Your Data Lives? Local vs. Remote OME-ZARR <a class="header-anchor" href="#does-it-matter-where-your-data-lives-local-vs-remote-ome-zarr" aria-label="Permalink to &quot;Does It Matter Where Your Data Lives? Local vs. Remote OME-ZARR&quot;">​</a></h1><p style="color:var(--vp-c-text-2);font-size:0.9em;">March 8, 2026 · Find Nuclei</p><p>Your microscopy files might be on a local SSD, a network share, or an S3 bucket on another continent. Find Nuclei Viewer works in all three cases — but what you experience will be very different.</p><p>There&#39;s a question that comes up often when people first try Find Nuclei Viewer: <em>&quot;Can I open files from our network drive?&quot;</em> The answer is yes. But the follow-up — <em>&quot;Will it be fast?&quot;</em> — depends entirely on how that network drive is set up. Before you commit to a storage strategy for your lab, core facility, or imaging pipeline, it&#39;s worth understanding why.</p><h2 id="same-image-two-very-different-experiences" tabindex="-1">Same Image, Two Very Different Experiences <a class="header-anchor" href="#same-image-two-very-different-experiences" aria-label="Permalink to &quot;Same Image, Two Very Different Experiences&quot;">​</a></h2><p>To make this concrete, watch what happens when we open the same large OME-ZARR dataset in two browser tabs — one reading from local disk, one streaming from a remote server.</p><div class="info custom-block"><p class="custom-block-title">🎬 Video Coming Soon</p><p>Side-by-side: the same HCS plate opened from local disk (left) and streamed from IDR over HTTPS (right). Notice how tiles fill in from coarse to fine on the remote side as each pyramid level is fetched, while local tiles appear near-instantly.</p></div><p>What you&#39;re seeing isn&#39;t a flaw — it&#39;s OME-ZARR working exactly as designed. The viewer fires off small HTTP-style requests for only the chunks inside your current viewport. Local or remote, the request pattern is the same. What changes is the cost of satisfying those requests.</p><h2 id="why-ome-zarr-can-be-streamed-at-all" tabindex="-1">Why OME-ZARR Can Be Streamed at All <a class="header-anchor" href="#why-ome-zarr-can-be-streamed-at-all" aria-label="Permalink to &quot;Why OME-ZARR Can Be Streamed at All&quot;">​</a></h2><p>Traditional microscopy formats — OME-TIFF, CZI, LIF — are largely monolithic. Displaying a single field of view can mean reading metadata scattered across a large file and decompressing contiguous chunks you don&#39;t actually need.</p><p>OME-ZARR flips this model. Data is stored as a <strong>chunked, multi-resolution pyramid</strong>: each zoom level is a separate set of small tile files, and the viewer only fetches the chunks that fall inside your current viewport. Zoom out to see a 96-well plate overview and you&#39;re loading tiny low-resolution tiles. Zoom into a single nucleus and only the high-resolution chunks for that region are requested — nothing else.</p><p>Find Nuclei Viewer is built entirely around this access pattern. It speaks directly to OME-ZARR stores over the <strong>File System Access API</strong> (for local files) or standard <strong>HTTP range requests</strong> (for remote URLs), with GPU-accelerated tile rendering in the browser. No server-side processing, no upload step.</p><h2 id="the-storage-setup-is-the-variable" tabindex="-1">The Storage Setup Is the Variable <a class="header-anchor" href="#the-storage-setup-is-the-variable" aria-label="Permalink to &quot;The Storage Setup Is the Variable&quot;">​</a></h2><p>When you drag a local folder into the viewer, your browser reads chunks directly from the filesystem — an NVMe SSD returns those in microseconds. A spinning hard drive is slower, but still local: no network latency, no contention with other users.</p><p>When you paste a remote URL, every chunk becomes an HTTP range request. This is where your infrastructure starts to matter.</p><h3 id="http-and-s3-compatible-object-storage" tabindex="-1">HTTP and S3-Compatible Object Storage <a class="header-anchor" href="#http-and-s3-compatible-object-storage" aria-label="Permalink to &quot;HTTP and S3-Compatible Object Storage&quot;">​</a></h3><p>These are purpose-built for this pattern. Range requests are first-class citizens. A well-configured object store — AWS S3, Azure Blob Storage, or a self-hosted MinIO instance — will serve hundreds of small chunk requests efficiently, and browser caching makes frequently-accessed tiles feel near-instant on subsequent views.</p><p><a href="https://min.io/" target="_blank" rel="noreferrer">MinIO</a> in particular is worth knowing about: it&#39;s an open-source, S3-compatible object store you can run on-premises on top of existing hardware, making it a practical choice for pharma or academic environments that can&#39;t move sensitive data to public cloud.</p><h3 id="nfs-and-smb-network-shares" tabindex="-1">NFS and SMB Network Shares <a class="header-anchor" href="#nfs-and-smb-network-shares" aria-label="Permalink to &quot;NFS and SMB Network Shares&quot;">​</a></h3><p>These protocols were designed for file-level access by local network clients, not for the burst-of-small-requests pattern that a chunked viewer generates. Each chunk request incurs round-trip overhead that compounds quickly — especially over VPN or when the NFS server is under load from other users.</p><p>A dataset that opens smoothly from a local SSD may feel sluggish when accessed from an NFS mount, even on a fast internal network. You may find that streaming the same file from a properly configured HTTP endpoint is noticeably faster than reading it from an SMB share presented as a mapped drive.</p><h2 id="what-this-means-in-practice" tabindex="-1">What This Means in Practice <a class="header-anchor" href="#what-this-means-in-practice" aria-label="Permalink to &quot;What This Means in Practice&quot;">​</a></h2><p><strong>Pharma and biotech labs</strong> running high-content screening produce terabytes of imaging data per run. The instinct is often to mount central storage as a network drive and open files from there. That works — but if performance is poor, the fix isn&#39;t necessarily to copy data to local disk. Putting an HTTP layer in front of your existing storage is often enough. MinIO can sit in front of a NAS or object store and expose it as an S3-compatible endpoint; nginx can serve a directory of Zarr files over HTTP with a few lines of configuration. Your data stays in one place, multiple users can access it simultaneously, and the viewer&#39;s chunked request pattern works as intended.</p><p><strong>Academic labs and core facilities</strong> get the same performance benefit — plus Find Nuclei Viewer&#39;s shareable deep links. Once your data is on HTTP-accessible storage, you can share a URL that opens to your exact view: same position, zoom level, channel settings, and colors. No file transfers, no emailing 50 GB datasets. Publicly available datasets on IDR and EMBER are already served this way — try pasting one of the example URLs from our <a href="https://find-nuclei.github.io/demos.html" target="_blank" rel="noreferrer">demos page</a> to see it in action.</p><p><strong>For sensitive or pre-publication data</strong>, the local drag-and-drop mode means your data never leaves the machine. No upload, no account, no server in the loop — the viewer runs entirely in the browser. That&#39;s the right choice when data governance or IP protection matters.</p><h2 id="a-quick-reference-for-common-setups" tabindex="-1">A Quick Reference for Common Setups <a class="header-anchor" href="#a-quick-reference-for-common-setups" aria-label="Permalink to &quot;A Quick Reference for Common Setups&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Storage Setup</th><th>How to Open</th><th>Chunk Request Behavior</th></tr></thead><tbody><tr><td><strong>Local SSD / HDD</strong></td><td>Drag &amp; drop folder</td><td>File System Access API — no network involved</td></tr><tr><td><strong>NFS / SMB mounted as local drive</strong></td><td>Drag &amp; drop folder</td><td>File System API, but network-backed — latency varies</td></tr><tr><td><strong>nginx serving a directory over HTTP</strong></td><td>Paste remote URL</td><td>HTTP range requests — efficient</td></tr><tr><td><strong>MinIO or S3-compatible store</strong></td><td>Paste remote URL</td><td>HTTP range requests — efficient, scales to many users</td></tr><tr><td><strong>Public repositories (IDR, EMBER)</strong></td><td>Paste remote URL</td><td>HTTP — publicly accessible, no setup required</td></tr></tbody></table><p>The OME-ZARR format is the same in every case. What changes is the infrastructure underneath.</p><h2 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h2><p>Both datasets shown in the video are publicly available on IDR. You can open them directly in the viewer right now — no download, no account:</p><ul><li><p><strong>Single image (idr0079):</strong><code>https://uk1s3.embassy.ebi.ac.uk/idr/zarr/v0.4/idr0079A/idr0079_images.zarr</code></p></li><li><p><strong>96-well HCS plate (idr0001):</strong><code>https://uk1s3.embassy.ebi.ac.uk/idr/zarr/v0.4/idr0001A/2551.zarr</code></p></li></ul><p>Paste either URL into <a href="https://find-nuclei.github.io" target="_blank" rel="noreferrer">Find Nuclei Viewer</a> and you&#39;re streaming a real dataset from EBI&#39;s infrastructure. Then open a local OME-ZARR folder in a second tab and compare.</p><p>The goal isn&#39;t to declare one approach universally faster. It&#39;s to understand what&#39;s happening under the hood so you can make a deliberate choice about your storage setup — rather than discovering that your NFS mount wasn&#39;t designed for this access pattern after you&#39;ve already built your pipeline around it.</p><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><ul><li><strong>Find Nuclei Viewer</strong> is a free, browser-based OME-ZARR viewer. No install, no upload, no account required.</li><li>It supports <strong>local files</strong> via drag-and-drop (File System Access API) and <strong>remote files</strong> via HTTP/HTTPS URL.</li><li>Supported remote storage includes HTTP servers, S3-compatible stores (AWS S3, MinIO), and any public OME-ZARR endpoint.</li><li>NFS and SMB mounts work but may perform poorly due to per-chunk latency; wrapping them with an HTTP layer (nginx, MinIO) is recommended for multi-user or high-throughput environments.</li><li>For sensitive data, local mode ensures <strong>data never leaves the machine</strong>.</li><li>Shareable deep links work for any remotely-hosted dataset.</li></ul><p style="text-align:center;margin-top:2em;"><a href="https://find-nuclei.github.io" style="display:inline-block;padding:0.75em 2em;background:var(--vp-c-brand-1);color:white;border-radius:8px;text-decoration:none;font-weight:600;">Try Find Nuclei Viewer →</a></p>',36)])])}const m=t(s,[["render",n]]);export{p as __pageData,m as default};
